    def write_denial_reference(code,*,operand='source',kind='NATIVE_IMMUTABLE_V2',fault=None):
        from types import SimpleNamespace
        import threading
        lease=o._LinuxPreflightHostLeaseV1.__new__(o._LinuxPreflightHostLeaseV1)
